<?php
require_once dirname(__DIR__,2).'/resources/require.php';require_once PROJECT_ROOT.'/resources/check_auth.php';
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');
pbx_admin::openPreferred();$access=new pbx_staff_access;if(!$access->owner()&&!$access->active()){http_response_code(403);exit('Sign in with your PBX staff account.');}
$meet=new pbx_meet;$error='';$notice='';$invitation=null;
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!(new token)->validate('/app/pbx_meet/index.php')){http_response_code(403);throw new DomainException('Refresh this page and try again.');}
  $action=$_POST['action']??'';$id=is_string($_POST['id']??null)?$_POST['id']:'';
  if($action==='create')$invitation=$meet->create($_POST);
  elseif($action==='invite')$invitation=$meet->invite($id);
  elseif($action==='host'){$handoff=bin2hex(random_bytes(16));$account=$meet->host($id);foreach($_SESSION['pbx_meet_handoffs']??[]as$key=>$value)if(($value['created']??0)<time()-300)unset($_SESSION['pbx_meet_handoffs'][$key]);$_SESSION['pbx_meet_handoffs'][$handoff]=['created'=>time(),'account'=>$account];header('Location: /app/pbx_meet/join.php?host='.$handoff);exit;}
  elseif($action==='email'){$count=$meet->emailInvitations($id,(string)($_POST['url']??''),(string)($_POST['emails']??''));$notice=$count.' invitations queued through the global outgoing mail server.';}
  elseif($action==='cancel'){if(empty($_POST['confirm_cancel']))throw new InvalidArgumentException('Confirm that you want to end this meeting.');$meet->cancel($id);$notice='Meeting ended. Existing invitations no longer work.';}
  elseif($action==='calendar'){$bytes=$meet->calendar($id,is_string($_POST['url']??null)?$_POST['url']:'');header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: attachment; filename="openweb-meeting.ics"');echo $bytes;exit;}
  else throw new InvalidArgumentException('Choose a meeting action.');
 }
 $meetings=$meet->meetings();
}catch(Throwable $ex){$error=$ex instanceof PDOException?'Your meeting could not be saved. Please try again.':$ex->getMessage();$meetings=[];}
$e=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');$token=(new token)->create('/app/pbx_meet/index.php');$csrf=static function()use($e,$token){echo '<input type="hidden" name="'.$e($token['name']).'" value="'.$e($token['hash']).'">';};
$document['title']='Meet';require PROJECT_ROOT.'/resources/header.php';
?>
<link rel="stylesheet" href="/app/pbx_setup/setup.css"><link rel="stylesheet" href="/app/pbx_meet/meet.css">
<main class="pbx-setup"><header class="setup-heading"><div><span class="setup-eyebrow">OPENWEB PBX</span><h1>Meet</h1><p>Start an audio or video meeting. Invite anyone with a private link. Your meeting opens in a new tab.</p></div><a class="setup-button" href="/app/pbx_setup/">Admin</a></header>
<?php if($error): ?><p class="setup-message error" role="alert"><?= $e($error) ?></p><?php endif; ?>
<?php if($notice): ?><p class="setup-message" role="status"><?= $e($notice) ?></p><?php endif; ?>
<?php if($invitation): ?><section class="meet-card"><h2>Invite Participants</h2><p>Share this link privately. Guests enter their name and wait for you to admit them.</p><input id="invitation" aria-label="Meeting invitation" readonly value="<?= $e($invitation['url']) ?>"><p>PBX dial-in: <strong><?= $e($invitation['dial_number']) ?></strong>. Use an extension on this PBX; the host admits phone participants too.</p><form method="post" target="_blank"><?php $csrf(); ?><input type="hidden" name="action" value="host"><input type="hidden" name="id" value="<?= $e($invitation['id']) ?>"><button class="setup-button primary">Start Now</button></form><form method="post"><?php $csrf(); ?><input type="hidden" name="action" value="calendar"><input type="hidden" name="id" value="<?= $e($invitation['id']) ?>"><input type="hidden" name="url" value="<?= $e($invitation['url']) ?>"><button class="setup-button">Download Calendar Invitation (.ics)</button></form><form method="post" class="setup-form"><?php $csrf(); ?><input type="hidden" name="action" value="email"><input type="hidden" name="id" value="<?= $e($invitation['id']) ?>"><input type="hidden" name="url" value="<?= $e($invitation['url']) ?>"><label>Email Participants<input name="emails" placeholder="person@example.com, colleague@example.com" required maxlength="5100"></label><button class="setup-button">Send Invitations</button></form></section><?php endif; ?>
<section class="meet-card"><h2>New Conference</h2><form method="post" class="setup-form"><?php $csrf(); ?><input type="hidden" name="action" value="create"><div class="setup-fields"><label>Subject<input name="subject" required maxlength="120" placeholder="Team meeting"></label><label>When<input type="datetime-local" name="local_start"><small>Leave blank to start now. Times use your browser's timezone.</small></label><input type="hidden" name="starts_at"><label>Duration (minutes)<input name="minutes" type="number" min="15" max="480" value="60" required></label><label>Notes to Participants<textarea name="notes" maxlength="2000"></textarea></label><label class="setup-check-label"><input type="checkbox" name="audio_only" value="1">Audio conference (no camera)</label><label class="setup-check-label"><input type="checkbox" name="open_join" value="1">Let invited guests join without waiting for admission</label></div><button class="setup-button primary">Create Meeting</button></form></section>
<section><h2>Your Meetings</h2><div class="meet-cards"><?php foreach($meetings as$m): ?><article class="meet-card"><h3><?= $e($m['subject']) ?></h3><p><time datetime="<?= $e($m['starts_at']) ?>"><?= $e($m['starts_at']) ?></time> · <?= $m['video_enabled']?'Video':'Audio' ?></p><p><?= $e($m['notes']) ?></p><p>PBX meeting number: <?= $e($m['dial_number']) ?></p><?php if($m['ended_at']): ?><p>Ended</p><?php else: ?><form method="post"><?php $csrf(); ?><input type="hidden" name="id" value="<?= $e($m['meeting_uuid']) ?>"><button class="setup-button primary" name="action" value="host" formtarget="_blank">Start / Join as Host</button><button class="setup-button" name="action" value="invite">New Invitation Link</button></form><small>A new link replaces the previous invitation. People already admitted stay connected.</small><details><summary>Cancel Meeting</summary><form method="post"><?php $csrf(); ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?= $e($m['meeting_uuid']) ?>"><label><input name="confirm_cancel" type="checkbox" value="1" required>End this meeting for everyone</label><button class="setup-button">End Meeting</button></form></details><?php endif; ?></article><?php endforeach; ?></div></section></main><script src="/app/pbx_meet/admin.js" defer></script>
<?php require PROJECT_ROOT.'/resources/footer.php'; ?>
